mapper.select:
SELECT ISSUE_ID, SCRN_ID, REG_EMPNO, ERR_CNTT, CASE WHEN FILE_DATA IS NULL THEN 0 ELSE 1 END AS HAS_IMAGE, STAT_CD, PRIR_CD, RSLV_CNTT, CREATED_AT, CREATED_BY, UPDATED_AT, UPDATED_BY FROM DASH_ISSUE
STAT_CD IN #{s}
AND SCRN_ID = #{screenId}
ORDER BY ISSUE_ID DESC

SELECT CMT_ID, ISSUE_ID, REG_EMPNO, CMT_CNTT,
       CREATED_AT, CREATED_BY, UPDATED_AT, UPDATED_BY
  FROM DASH_ISSUE_CMT
 WHERE ISSUE_ID = #{issueId}
   AND CMT_ID   = #{commentId}

mapper.update:
UPDATE DASH_ISSUE_CMT
   SET CMT_CNTT   = #{cmtCntt},
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{actor}
 WHERE ISSUE_ID = #{issueId}
   AND CMT_ID   = #{cmtId}

mapper.delete:
DELETE FROM DASH_ISSUE_CMT
 WHERE ISSUE_ID = #{issueId}
   AND CMT_ID   = #{commentId}
